import React, { useState } from 'react'
import { View, Text, TouchableOpacity, Dimensions, ActivityIndicator } from 'react-native'

import { useContexState } from '../../hooks/context';
import { styles } from './styles';

import api from '../../services/api';

export function PaymentMenu() {
    const { shoppingCartItem, setShoppingCartItem, selectedNumber, setSelectedNumber } = useContexState();
    const [startLoad, setStartLoad] = useState(false)

    function AddCart() {
        setStartLoad(true);
        api.post("register", {
            number: selectedNumber,
            name: 'CartSsetShoppingCartItemelect',
            phone: '(00)000000000',
        }).then((response) => {
            setStartLoad(false);
            setSelectedNumber(null);
            setShoppingCartItem([...shoppingCartItem, Number(selectedNumber)]);
        });
    };


    return (selectedNumber !== null ? <>
        <TouchableOpacity onPress={() => {
            setSelectedNumber(null);
        }} style={{
            position: 'absolute',
            alignItems: 'center',
            justifyContent: 'center',
            //    backgroundColor: '#fff',
            minWidth: Dimensions.get('window').width,
            minHeight: Dimensions.get('window').height
        }} />




        <View style={styles.container} >
            <Text style={[styles.listText]}>
                {(`0000${selectedNumber}`).slice(-4)}
            </Text>

            {startLoad ?
                <>
                    <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center', marginHorizontal: 10 }}>Adicionando ao carrinho!</Text>
                    <ActivityIndicator size={37} color='#fff' style={{ marginTop: 10, marginBottom: 20 }} />
                </> :

                <> <TouchableOpacity style={{
                    backgroundColor: '#26A744', borderRadius: 15, width: 230, padding: 10,
                }} >
                    <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center' }}>Comprar agora</Text>
                </TouchableOpacity>

                    <TouchableOpacity onPress={() => AddCart()} style={{ backgroundColor: '#17A2B7', borderRadius: 15, width: 230, padding: 10, margin: 10 }} >
                        <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center' }}>Adicionar ao {'\n'}carrinho</Text>
                    </TouchableOpacity>

                    <TouchableOpacity style={{
                        backgroundColor: '#DAA520', borderRadius: 15, width: 230, padding: 10,
                        marginBottom: 10
                    }} >
                        <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center' }}>Revender</Text>
                        <Text style={{ color: '#fff', fontSize: 16, textAlign: 'center' }}>Apenas para representantes!</Text>
                    </TouchableOpacity> </>}
        </View>



    </> : null
    );
};
